  "The server is busy. Try again in a moment.": "Serveren har travlt. Prøv igen om lidt.",
  "1 passkey": "1 adgangsnøgle",
  "A one-time code lets your phone or another computer sign in with a passkey of its own.": "En engangskode lader din telefon eller en anden computer logge ind med sin egen adgangsnøgle.",
  "Add a passkey": "Tilføj en adgangsnøgle",
