  "Code from your other device": "Kode fra din anden enhed",
  "Confirm with a passkey": "Bekræft med en adgangsnøgle",
  "Confirmed. Now create the new passkey; your browser will ask where to keep it.": "Bekræftet. Opret nu den nye adgangsnøgle; din browser spørger, hvor den skal gemmes.",
  "Copy link": "Kopiér link",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "Opret en adgangsnøgle på denne enhed til profilen “{0}”. Den logger dig ind her fremover.",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "Hver af dem logger ind på denne profil fra den enhed eller adgangskodemanager, der gemmer den. Tryk på en for at omdøbe eller fjerne den.",
  "Enter the code from your other device.": "Indtast koden fra din anden enhed.",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "Til denne enhed, en sikkerhedsnøgle, en adgangskodemanager eller din telefon via browserens egen QR-kode. Bekræft først, at det er dig.",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "Den kan ikke længere logge ind på denne profil. En enhed, der allerede er logget ind med den, forbliver logget ind. Hvis den er mistet, så brug Log ud overalt.",
  "It is your only way in, so it cannot be removed until there is another.": "Det er din eneste vej ind, så den kan ikke fjernes, før der er en til.",
  "Last used {0}": "Sidst brugt {0}",
  "Make a new code": "Lav en ny kode",
  "Name, e.g. Work laptop": "Navn, f.eks. Arbejdscomputer",
  "None yet. Add one and sign in without your password.": "Ingen endnu. Tilføj en, og log ind uden din adgangskode.",
  "Passkey added": "Adgangsnøgle tilføjet",
