  "Remove this passkey?": "Fjern denne adgangsnøgle?",
  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "Scan den med den anden enhed, eller åbn openGym dér og indtast koden på login-skærmen. Den virker én gang, i {0} minutter.",
  "That code is wrong, already used or expired. Make a new one on your other device.": "Koden er forkert, allerede brugt eller udløbet. Lav en ny på din anden enhed.",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "Denne browser kan ikke bekræfte med din adgangsnøgle. Gør det på en enhed, der har en.",
  "First confirm that it is you.": "Bekræft først, at det er dig.",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "Denne profil har ingen adgangsnøgle, og serveren tager ikke imod adgangskoder, så intet her kan bekræfte, at det er dig. Spørg din admin.",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "Denne browser kan ikke oprette adgangsnøgler, så den kan ikke tilføjes med en kode. Åbn linket i en browser, der kan.",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "Denne browser er logget ind som “{0}”. Hvis du tilføjer den til “{1}”, logges “{0}” ud her.",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "Denne kode er til en anden profil, der også hedder “{0}”, ikke den, browseren er logget ind som. Tilføjer du den dér, logges din ud her.",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "Fortsæt kun, hvis koden kommer fra en af dine egne enheder. Browseren bliver så logget ind på “{0}”, og det, du logger her, går til den profil.",
  "This code has expired.": "Koden er udløbet.",
