  "This profile already has as many passkeys as it can hold.": "Denne profil har allerede så mange adgangsnøgler, som den kan have.",
  "Use a code from your other device": "Brug en kode fra din anden enhed",
  "You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.": "Du får en kode, der lader din telefon eller en anden computer oprette en adgangsnøgle til denne profil. Bekræft først, at det er dig.",
