  "Saves a dated copy to Documents/openGym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.": "Gemmer en dateret kopi i Documents/openGym, når du afslutter en træning eller redigerer en rutine, og beholder de nyeste {0}. Peg en synkroniseringsapp på mappen, eller kopiér den ud manuelt.",
  "Reset everything?": "Nulstil alt?",
  "Reset everything": "Nulstil alt",
  "Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.": "Sletter din plan, dine træninger, din kropsvægt, fotos og videoer på denne enhed. Det kan ikke fortrydes.",
  "Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.": "Sletter din plan, dine træninger, din kropsvægt, fotos og videoer fra din profil på denne server og på alle enheder, der er logget ind. Det kan ikke fortrydes.",
  "Sync failed: the server refused the upload as too large. Your changes have not reached the server.": "Synkronisering mislykkedes: serveren afviste uploaden, fordi den var for stor. Dine ændringer er ikke nået frem til serveren.",
  "This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.": "Denne enhed er løbet tør for lagerplads: ændringen er ikke gemt her. Er du logget ind, sendes den stadig til serveren.",
