  "Deload routine": "Deload-rutine",
  "Its workouts do not count toward progression. They still show in history and statistics.": "Dens træninger tæller ikke med i progressionen. De vises stadig i historik og statistik.",
  "A deload routine opens at the numbers set here, so the progression above does not apply to it.": "En deload-rutine starter ved tallene angivet her, så progressionen ovenfor gælder ikke for den.",
