  "Add time": "Læg tid til",
  "Targets stay where you set them.": "Målene bliver, hvor du satte dem.",
  "Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.": "Klar hver rep i hvert sæt, så stiger vægten. Gentagne miss udløser en deload.",
  "Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.": "To normale sæt plus et sidste sæt til failure. Slå målet i det sæt, så stiger vægten (dobbelt så meget, hvis du fordobler reps). Ét miss sænker med 10 %.",
  "Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.": "Arbejd dig op gennem et rep-interval med samme vægt. Nå toppen af intervallet i hvert sæt, så stiger vægten, og reps går tilbage til bunden.",
  "Hold every set for the full duration and the target goes up.": "Hold hvert sæt hele tiden, så stiger målet.",
  "Nothing logged yet, so this session sets the baseline.": "Intet logget endnu, så denne træning sætter udgangspunktet.",
  "Held every set for the full time. Target goes up by {0}s.": "Holdt hvert sæt hele tiden. Målet stiger med {0} s.",
  "Short {0} sessions in a row. Back off to {1}s and build up again.": "For kort {0} træninger i træk. Gå ned til {1} s, og byg op igen.",
  "Came up short last time. Same target again.": "Kom til kort sidst. Samme mål igen.",
  "Top of the rep range in every set. {0} {1} more, back to {2} reps.": "Toppen af rep-intervallet i hvert sæt. {0} {1} mere, tilbage til {2} reps.",
  "Stuck for {0} sessions. Deload to {1} {2}.": "Gået i stå i {0} træninger. Deload til {1} {2}.",
  "Same weight, aim for {0} reps this time.": "Samme vægt, gå efter {0} reps denne gang.",
  "Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.": "Sidste sæt gav {0} reps, det dobbelte af målet! Tag et dobbelt hop på {1} {2}.",
  "Every rep last time. {0} {1} more.": "Hver rep sidst. {0} {1} mere.",
  "Every rep last time. {0} {1} less help.": "Hver rep sidst. {0} {1} mindre hjælp.",
  "Top of the rep range in every set. {0} {1} less help, back to {2} reps.": "Toppen af rep-intervallet i hvert sæt. {0} {1} mindre hjælp, tilbage til {2} reps.",
  "Missed reps. {0} {1} of help while you build back up.": "Missede reps. {0} {1} hjælp, mens du bygger op igen.",
  "Stuck for {0} sessions. Back to {1} {2} of help, then build up again.": "Gået i stå i {0} træninger. Tilbage til {1} {2} hjælp, og byg så op igen.",
