  "RIR": "RIR",
  "RPE": "RPE",
  "Effort per set": "Indsats pr. sæt",
  "What are RIR and RPE?": "Hvad er RIR og RPE?",
  "How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.": "Hvor hårdt et sæt var, logget ved siden af vægt og reps. To skalaer for samme vurdering, talt fra hver sin ende.",
  "How it felt": "Hvordan det føltes",
