  "How hard was that set?": "Hvor hårdt var det sæt?",
  "Tap how many reps you had left, or type an exact {0}.": "Tryk på, hvor mange reps du havde tilbage, eller skriv en præcis {0}.",
  "Exact {0}": "Præcis {0}",
  "Clear rating": "Ryd vurdering",
  "RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.": "RIR tæller de reps, du havde tilbage i tanken; RPE aflæser samme indsats på en 10-punktsskala, så RPE ≈ 10 − RIR. Vælg den, du allerede tænker i.",
  "The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.": "Den fremhævede række er der, hvor de fleste arbejdssæt lander. Sæt, du allerede har logget, beholder deres egen skala, og intet andet læser værdien, så progression og anslået 1RM påvirkes ikke.",
