  "Every muscle group got at least one hard set in this period.": "Alle muskelgrupper fik mindst ét hårdt sæt i denne periode.",
  "No rated sets in this period.": "Ingen vurderede sæt i denne periode.",
  "average effort": "gennemsnitlig indsats",
