  "Week by week": "Uge for uge",
  "Where the sets land": "Hvor sættene lander",
  "Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.": "De fleste arbejdssæt hører til tæt på failure, ikke ved den. Halvdelen i bunden og halvdelen i toppen giver stadig et gennemsnit, der ser sundt ud.",
  "Average effort per workout": "Gennemsnitlig indsats pr. træning",
  "A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.": "En fyldigere prik betyder mindre tilbage i tanken. Samme vægt ved en lavere {0} er fremskridt, som linjen alene ikke viser.",
  "Bodyweight": "Kropsvægt",
  "No weight to enter. Just log the reps.": "Ingen vægt at indtaste. Log bare dine reps.",
  "Ask for a weight on every set.": "Spørg om vægt i hvert sæt.",
  "For dips or pull-ups with a belt. Progression then follows the weight.": "Til dips eller pull-ups med vægtbælte. Progressionen følger så vægten.",
  "For lunges, single-arm rows and the like.": "Til udfaldsskridt, etarmsroning og lignende.",
  "Top of the range": "Toppen af intervallet",
