  "Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.": "Reps stiger til {0}, så tilføjes et sæt, og reps starter forfra. Ved {1} sæt beder den dig om at lægge vægt på i stedet.",
