  "Use on this device": "Brug på denne enhed",
  "Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.": "Lokalt holder alt på denne telefon. Forbinder du, synkroniseres der i stedet med din egen openGym-server. Du kan skifte senere i Indstillinger.",
  "{0} (done)": "{0} (færdig)",
  "Workout done": "Træning færdig",
  "reps": "reps",
  "Most reps in a set per workout": "Flest reps i ét sæt pr. træning",
  "Warm-up sets": "Opvarmningssæt",
  "Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, never below the bar on a barbell lift, and you can still change any of them mid-session.": "Lægges før dine arbejdssæt og tæller ikke med i volumen, rekorder og progression. Hvert sæt lukker halvdelen af afstanden til arbejdsvægten, aldrig under stangen på et vægtstangsløft, og du kan stadig ændre dem undervejs.",
  "Added before your work sets and left out of volume, records and progression. On an assistance machine each one has more help than the work set, stepping down toward it, and you can still change any of them mid-session.": "Lægges før dine arbejdssæt og tæller ikke med i volumen, rekorder og progression. På en assisteret maskine har hvert sæt mere hjælp end arbejdssættet og trapper ned mod det, og du kan stadig ændre dem undervejs.",
  "Ramp-up sets added before the work sets, so you do not have to add them by hand each session.": "Opbygningssæt lagt før arbejdssættene, så du ikke skal tilføje dem manuelt hver gang.",
  "Note": "Note",
  "This session": "Denne træning",
  "How it went, what to change. Saved with today’s workout.": "Hvordan det gik, hvad der skal ændres. Gemmes med dagens træning.",
  "Show this next time": "Vis næste gang",
  "Brings it up again the next time you train this exercise.": "Viser den igen næste gang, du træner denne øvelse.",
  "Always for this exercise": "Altid for denne øvelse",
  "Seat height, pin position, a form cue. Shown every session.": "Sædehøjde, stiftposition, en teknikpointe. Vises hver gang.",
  "From {0}:": "Fra {0}:",
