  "How the session went as a whole.": "Hvordan træningen gik som helhed.",
  "Rest-pause always trains as one warm-up set at this rep count, then one rest-pause work set. \"Sets\" isn’t used here.": "Rest-pause trænes altid som ét opvarmningssæt med dette antal reps og derefter ét rest-pause-arbejdssæt. \"Sæt\" bruges ikke her.",
  "(saved)": "(gemt)",
  "AI Coach": "AI-coach",
  "API key": "API-nøgle",
  "Bring my own API key": "Brug min egen API-nøgle",
  "Could not reach the provider: {0}": "Kunne ikke nå udbyderen: {0}",
  "Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted openGym”: your server can reach an http:// model on its own network.": "Android blokerer ukrypterede http://-forbindelser fra apps, så denne telefon kan kun nå et https://-endpoint. Sæt HTTPS foran (Tailscale eller en reverse proxy), eller vælg “Brug min selvhostede openGym”: din server kan nå en http://-model på sit eget netværk.",
  "Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.": "Hver forespørgsel går direkte til {0} med din nøgle. Ingen andre ser den, og du betaler for den.",
  "Endpoint": "Endpoint",
  "Enter your API key": "Indtast din API-nøgle",
  "Enter the endpoint URL": "Indtast endpointets URL",
  "There’s no routine to review yet. Build one with at least two exercises first.": "Der er ingen rutine at gennemgå endnu. Byg en med mindst to øvelser først.",
  "How should the Coach run?": "Hvordan skal coachen køre?",
  "List models": "Vis modeller",
  "Model": "Model",
  "Nothing to change right now: {0}": "Intet at ændre lige nu: {0}",
  "Off. Choose how the Coach should run.": "Fra. Vælg hvordan coachen skal køre.",
  "Pick a model": "Vælg en model",
  "Provider": "Udbyder",
  "Runs on this phone with your own API key": "Kører på denne telefon med din egen API-nøgle",
  "Runs on your openGym server": "Kører på din openGym-server",
  "Save and use the Coach": "Gem og brug coachen",
  "The Coach is already thinking about your training.": "Coachen tænker allerede over din træning.",
  "The Coach is taking a breather. You’ve used today’s {0} runs on this phone.": "Coachen tager en pust. Du har brugt dagens {0} kørsler på denne telefon.",
  "The Coach isn’t set up on this phone.": "Coachen er ikke sat op på denne telefon.",
  "The Coach needs your go-ahead first.": "Coachen skal have dit go først.",
  "The key is stored in this phone’s secure storage and never leaves it except to call the provider.": "Nøglen gemmes i telefonens sikre lager og forlader den aldrig, undtagen for at kalde udbyderen.",
  "This phone calls the provider directly with your key. Every request is charged to your account.": "Denne telefon kalder udbyderen direkte med din nøgle. Hver forespørgsel afregnes på din konto.",
  "Turn the Coach off on this phone": "Slå coachen fra på denne telefon",
  "Use my self-hosted openGym": "Brug min selvhostede openGym",
  "What leaves this phone": "Hvad der forlader denne telefon",
  "Your server has no Coach enabled. Ask its admin, or bring your own key below.": "Din server har ingen coach slået til. Spørg dens admin, eller brug din egen nøgle nedenfor.",
  "Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.": "Din server kører coachen med den udbyder, dens admin har sat op. Intet nyt forlader telefonen ud over det, der allerede synkroniseres.",
  "Loading the exercise catalogue…": "Indlæser øvelseskataloget…",
  "Checking the endpoint…": "Tjekker endpointet…",
  "A local model can take longer.": "En lokal model kan tage længere tid.",
  "All optional. The more the Coach knows, the less it guesses.": "Alt er valgfrit. Jo mere coachen ved, jo mindre gætter den.",
  "Almost there": "Næsten færdig",
  "Avoid: {0}": "Undgå: {0}",
  "Before we start": "Før vi starter",
  "Building your plan…": "Bygger din plan…",
  "Discarded. Tell me what was off and I will build a different one.": "Kasseret. Fortæl mig, hvad der var galt, så bygger jeg en anden.",
  "Done! Your plan is back to how it was before my last changes.": "Færdig! Din plan er tilbage, som den var før mine seneste ændringer.",
  "Edit my answers": "Rediger mine svar",
  "Start a new plan": "Start en ny plan",
  "A fresh plan from your answers; your workouts stay": "En ny plan ud fra dine svar; dine træninger bliver",
  "Build me a fresh plan from my answers.": "Byg mig en ny plan ud fra mine svar.",
  "Experience": "Erfaring",
  "Goal, days, equipment, limits": "Mål, dage, udstyr, begrænsninger",
  "Have a look at my training and tell me what you would change.": "Kig på min træning, og fortæl mig, hvad du ville ændre.",
  "Here is what I am working with:": "Det her arbejder jeg ud fra:",
  "Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.": "Hej, jeg er din coach. Jeg bygger din plan ud fra dine svar og justerer den efter det, du faktisk logger. Intet ændres, før du siger til.",
  "I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.": "Jeg har kigget det hele igennem, og der er intet, jeg ville ændre lige nu. Bliv ved, og spørg mig igen efter et par træninger mere.",
  "I understand, let’s go": "Forstået, lad os komme i gang",
  "Imported! {0} routines are in your plan and your week is set. See you at the next session.": "Importeret! {0} rutiner er i din plan, og din uge er sat op. Vi ses til næste træning.",
  "Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.": "Importeret! {0} rutiner er i din plan. Din uge er uændret; planlæg dem, når du vil.",
  "It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.": "Den designer din plan ud fra et par svar og justerer den efter det, du faktisk logger. Den ændrer aldrig noget uden dit ja, og du kan fortryde hver ændring.",
  "Routines, exercises, sets and reps, your weekly schedule and progression settings.": "Rutiner, øvelser, sæt og reps, din ugeplan og progressionsindstillinger.",
  "Your logged training": "Din loggede træning",
  "Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.": "Sæt, du har logget i gennemgangsperioden: vægte, reps, tider, indsatsvurderinger, hvor lang tid træningerne tog, og dine træningsnoter.",
  "Weigh-ins from the same window, and your goal weight if you set one.": "Vejninger fra samme periode og din målvægt, hvis du har sat en.",
  "What you tell the Coach": "Det, du fortæller coachen",
  "Your intake answers, including any limitations or injuries you describe.": "Dine svar fra opstarten, inklusive begrænsninger eller skader, du beskriver.",
  "A few preferences": "Et par præferencer",
  "Your unit, your language and which effort scale you log.": "Din enhed, dit sprog og hvilken indsatsskala du logger med.",
