  "{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} træninger og {1} vejninger blev logget på denne enhed, mens du var logget ud. Tilføj dem til din profil, eller behold profilen præcis som på serveren.",
  "{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} træning og {1} vejning blev logget på denne enhed, mens du var logget ud. Tilføj dem til din profil, eller behold profilen præcis som på serveren.",
  "{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} træning og {1} vejninger blev logget på denne enhed, mens du var logget ud. Tilføj dem til din profil, eller behold profilen præcis som på serveren.",
  "{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} træninger og {1} vejning blev logget på denne enhed, mens du var logget ud. Tilføj dem til din profil, eller behold profilen præcis som på serveren.",
