  "Your server’s address answered with something other than openGym (HTTP {0}). Your changes are kept here.": "Din servers adresse svarede med noget andet end openGym (HTTP {0}). Dine ændringer gemmes her.",
  "Server error (HTTP {0})": "Serverfejl (HTTP {0})",
  "Your server answered with an error (HTTP {0}). Your changes are kept here.": "Din server svarede med en fejl (HTTP {0}). Dine ændringer gemmes her.",
  "The server refuses this browser": "Serveren afviser denne browser",
  "Your server no longer accepts this browser. Your changes are kept here.": "Din server accepterer ikke længere denne browser. Dine ændringer gemmes her.",
