  "Some changes on this device have not reached your server.": "Nogle ændringer på denne enhed er ikke nået frem til din server.",
  "Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Prøv igen, eller eksportér en backup først. Fortsætter du alligevel, gemmes en kopi af ændringerne på denne enhed, indtil den forbinder til serveren som denne konto igen. Så lægges de tilbage.",
