  "Server & sync": "Server og synkronisering",
  "Signed in as {0}": "Logget ind som {0}",
  "Sync now": "Synkronisér nu",
  "Your changes are kept here, and merged into your account once it is paired again.": "Dine ændringer gemmes her og flettes ind i din konto, når den er parret igen.",
  "Your changes are kept here, and merged into your account once you are signed in again.": "Dine ændringer gemmes her og flettes ind i din konto, når du er logget ind igen.",
  "Changes kept for {0}": "Ændringer gemt for {0}",
  "Added back when this device connects as that account again.": "Lægges tilbage, når denne enhed forbinder som den konto igen.",
  "The changes your server has not seen are kept on this device, and added back when it connects as this account again.": "Ændringerne, din server ikke har set, gemmes på denne enhed og lægges tilbage, når den forbinder som denne konto igen.",
  "This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.": "Telefonen skifter tilbage til kun lokalt, og dens kopi af din konto fjernes. Først tjekkes det, at din server har alle ændringer. Hvis ikke, vælger du, hvad der sker med dem.",
  "Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.": "Dine data fjernes fra denne browser; din profil på serveren beholder dem. Først tjekkes det, at serveren har alle ændringer. Hvis ikke, vælger du, hvad der sker med dem.",
  "Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.": "Logger profilen ud på alle enheder, også denne. Telefoner, der er parret med den, afbrydes og skal parres igen. Dine adgangsnøgler virker stadig, så du kan logge ind med dem igen når som helst.",
