  "{0} changes": "{0} ændringer",
  "Default progression": "Standardprogression",
  "Planned sessions start from": "Planlagte træninger starter fra",
  "The routine’s sets and reps. Your history decides the weight.": "Rutinens sæt og reps. Din historik bestemmer vægten.",
  "Your last session": "Din seneste træning",
  "The reps you logged last time in that routine, carried over, and any warm-ups you set up yourself. With progression off, the weight too.": "De reps, du loggede sidst i den rutine, overført, plus opvarmningssæt, du selv har sat op. Med progression slået fra også vægten.",
