  "Close editor": "Luk editoren",
  "Editing a saved workout. Date and duration stay unchanged.": "Redigerer en gemt træning. Dato og varighed forbliver uændret.",
  "A pull for every press, so the shoulders stay balanced.": "Et træk for hvert pres, så skuldrene holdes i balance.",
  "A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.": "En todagesrotation over tre træninger om ugen, bygget op om det udstyr, du angav. Basisøvelser først, ét træk for hvert pres og nok overlap mellem dagene til, at intet går to uger uden at blive trænet.",
  "Based on the training already in this demo profile.": "Baseret på træningen, der allerede er i denne demoprofil.",
  "Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.": "Kropsvægten har stået stille i fire uger, mens målet er at tage på. Det er et køkkenproblem, ikke et træningsproblem. Det er ikke planen, der holder igen.",
  "Demo": "Demo",
  "Demo data reset": "Demodata nulstillet",
  "Direct arm work, since you asked for it.": "Direkte armtræning, fordi du bad om det.",
  "Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.": "Hvert topsæt her lå på RPE 9,5 eller derover i tre træninger, og vægten har ikke rykket sig. At bytte bevægelsen i fire uger bryder som regel sådan et plateau hurtigere end at slide videre på den samme.",
  "Example data, stored only in this browser. Go wild and change anything you like.": "Eksempeldata, kun gemt i denne browser. Gå amok og ændr alt, hvad du vil.",
  "Full body A": "Helkrop A",
  "Full body B": "Helkrop B",
  "Horizontal pressing, the other half of the session.": "Horisontalt pres, den anden halvdel af træningen.",
  "Live demo. Everything stays in this browser.": "Live-demo. Alt bliver i denne browser.",
  "No training history yet, so starting conservatively.": "Ingen træningshistorik endnu, så vi starter forsigtigt.",
  "Passkey sign-in, sync across your devices, your own data.": "Login med adgangsnøgle, synkronisering på tværs af dine enheder, dine egne data.",
  "Puts the example plan, workouts and weigh-ins back the way they started.": "Sætter eksempelplanen, træningerne og vejningerne tilbage, som de var fra start.",
  "Reset": "Nulstil",
  "Reset demo data": "Nulstil demodata",
  "Reset demo data?": "Nulstil demodata?",
  "Revised as you asked. Everything you did not question is exactly as it was.": "Revideret som ønsket. Alt, du ikke satte spørgsmålstegn ved, er præcis som før.",
  "Same pattern, higher reps than day A.": "Samme mønster, flere reps end dag A.",
  "Self-host it in a minute →": "Selvhost den på et minut →",
  "Self-host openGym": "Selvhost openGym",
  "Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.": "Træningerne har trukket ca. et kvarter over. Det her er den hjælpeøvelse, der mister mindst ved ét sæt færre.",
  "Start the demo": "Start demoen",
  "The main lower-body driver, where most of the strength comes from.": "Den vigtigste drivkraft for underkroppen, hvor det meste af styrken kommer fra.",
  "The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.": "Samme mønstre, andre varianter: nok overlap til at gøre fremskridt, nok forskel til at holde det frisk.",
  "The two big lower-body and pressing patterns first, while you are fresh.": "De to store mønstre for underkrop og pres først, mens du er frisk.",
  "This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.": "Denne demo kører helt i din browser med eksempeldata. Intet sendes nogen steder hen. Login med adgangsnøgle og synkronisering på tværs af enheder følger med openGym-serveren, som du får ved at selvhoste den.",
  "Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.": "Tre ting, der er værd at ændre, og én, der er værd at vide. Alt andet virker: squat og træk går begge fremad efter planen.",
  "Vertical pressing.": "Vertikalt pres.",
  "You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.": "Du har flyttet denne træning til lørdag tre uger i træk. Bedre at planen siger det, end at du bliver ved med at overstyre den.",
  "You’re in the demo": "Du er i demoen",
