  "Drill sergeant": "Drillsergent",
  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "Ét prik om aftenen på en planlagt dag uden noget logget, mellem 20:00 og 21:30. Efter 3 missede dage i træk bliver det stille til din næste træning.",
  "Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.": "Logget en træning på en anden enhed? Før prikket sendes, tjekker telefonen med din server, når den lader appen køre i baggrunden. Åbner du appen, kommer den altid ajour.",
  "Everything okay?": "Er alt okay?",
  "{0} is still waiting. What’s up?": "{0} venter stadig. Hvad sker der?",
  "No {0} today? Even a short session tomorrow counts.": "Ingen {0} i dag? Selv en kort træning i morgen tæller.",
  "Rough day? {0} will keep. Tomorrow is a fresh start.": "Hård dag? {0} kan vente. I morgen er en ny dag.",
  "Hey, {0} didn’t happen today. All good?": "Hej, {0} blev ikke til noget i dag. Alt godt?",
  "I miss you": "Jeg savner dig",
  "{0} waited by the door all evening. For you.": "{0} ventede ved døren hele aftenen. På dig.",
  "The barbell asked about you today. I didn’t know what to say.": "Vægtstangen spurgte efter dig i dag. Jeg vidste ikke, hvad jeg skulle sige.",
  "Was it something I said? {0} misses you.": "Var det noget, jeg sagde? {0} savner dig.",
  "I saved you a spot on the bench. It’s still empty.": "Jeg holdt en plads på bænken til dig. Den er stadig tom.",
  "Attention, recruit!": "Ret ind, rekrut!",
  "Your gains are packing their bags. {0} tomorrow, no excuses!": "Dine gains pakker kufferten. {0} i morgen, ingen undskyldninger!",
  "{0} doesn’t do itself, recruit. Move it!": "{0} laver ikke sig selv, rekrut. Kom i gang!",
  "Excuses don’t lift weights. Report for {0} tomorrow!": "Undskyldninger løfter ikke vægte. Meld dig til {0} i morgen!",
  "Your muscles filed a missing-person report. Show up for {0}!": "Dine muskler har meldt dig savnet. Mød op til {0}!",
  "That address answers, but it isn’t an openGym server. Check the URL.": "Adressen svarer, men det er ikke en openGym-server. Tjek URL’en.",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Adressen svarer, men en login-side eller proxyregel svarede i stedet for openGym. Lad /api/ gå uændret igennem til openGym. Se “Phone app and CORS” i docs/SELF_HOSTING.md.",
  "Switch sides": "Skift side",
  "Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.": "Gemmer en dateret kopi i “{0}”, når du afslutter en træning eller redigerer en rutine, og beholder de nyeste {1}.",
  "Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.": "Gemmer en dateret kopi i den mappe, du valgte, når du afslutter en træning eller redigerer en rutine, og beholder de nyeste {0}.",
  "Plan options": "Planindstillinger",
  "Your routines in a loop": "Dine rutiner i et loop",
  "Back to a fixed week?": "Tilbage til en fast uge?",
  "The loop stops. Your weekdays stay as they are, and the loop is saved for later.": "Loopet stopper. Dine ugedage forbliver som de er, og loopet gemmes til senere.",
  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "Rutiner i et loop. Det, der står som det næste, bliver stående, til du træner det, uanset dag.",
  "The same routines on the same weekdays, every week.": "De samme rutiner på de samme ugedage, hver uge.",
  "How you train": "Sådan træner du",
