  "No account, no cloud. Back it up anytime in Data & backup.": "Ingen konto, ingen sky. Tag en backup når som helst under Data og backup.",
  "Effort per set is off. Turn it on in Settings → Workout to keep rating.": "Indsats pr. sæt er slået fra. Slå det til under Indstillinger → Træning for at blive ved med at vurdere.",
  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "Indtast koden, som din anden enhed viser under Indstillinger → Konto → Tilføj en anden enhed. Denne enhed får så sin egen adgangsnøgle.",
  "Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.": "Åbn Indstillinger → Konto → “Par mobilappen” på den openGym-side, du allerede er logget ind på, og indtast derefter dens adresse og koden, der vises der.",
  "Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.": "Åbn Indstillinger → Konto → “Par mobilappen” på din openGym-side i en browser, og indtast den nye kode, der vises der. Det, telefonen har gemt, bliver flettet ind i din konto.",
