  "Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Din plan, dine noter eller centerkort på denne enhed blev oprettet, mens du var logget ud. Tilføj dem til din profil, eller behold profilen præcis som den er på serveren.",
