  "Dumbbells": "Håndvægte",
  "The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.": "Vægtene du har, én håndvægt hver. Progression, deloads, opvarmning og knapperne + og − ved håndvægtsøvelser lander kun på disse.",
