  "{0} reps in every set! Add a set at {1} reps.": "{0} gentagelser i hvert sæt! Tilføj et sæt med {1} gentagelser.",
  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "Toppen af intervallet i alle {0} sæt. {1} {2} mere, tilbage til {3} sæt á {4}.",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "Toppen af intervallet i alle {0} sæt. {1} {2} mindre hjælp, tilbage til {3} sæt á {4}.",
