  "Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.": "Hvem coachen må sende din træning til fra denne enhed. Træk det tilbage, så spørger coachen igen næste gang. En model på dit eget netværk behøver aldrig spørge.",
