  "Set the bar once for every exercise of a type.": "Indstil stangen én gang for alle øvelser af en type.",
  "Your bar for this type, set in Your bars.": "Din stang for denne type, indstillet under Dine stænger.",
  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "Hvad stængerne i dit center vejer. Hver øvelse med den stang tæller skiver ud fra den, medmindre du har givet øvelsen sin egen. Loggede vægte forbliver totalvægte.",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "De fleste løft i biblioteket bruger “{0}”, nogle få bruger “{1}”. En kort stang til dem alle betyder, at du indstiller begge.",
  "Back to the standard bars": "Tilbage til standardstængerne",
  "Standard bars. Tap if yours are lighter.": "Standardstænger. Tryk, hvis dine er lettere.",
  "The last warm-up still gets the full rest before your first work set.": "Det sidste opvarmningssæt får stadig den fulde pause før dit første arbejdssæt.",
  "Days per week": "Dage om ugen",
