  "Not trained:": "Ikke trænet:",
  "Rounded to whole sets. A set counts fully for its main muscle and partly for the ones that help, so the muscles add up to more than your work sets.": "Afrundet til hele sæt. Et sæt tæller fuldt for sin hovedmuskel og delvist for dem, der hjælper, så musklerne giver tilsammen flere end dine arbejdssæt.",
  "One session in this period.": "Én træning i denne periode.",
  "No workouts in this period.": "Ingen træninger i denne periode.",
  "Consistency": "Regelmæssighed",
