  "Estimated 1RM, top lifts": "Anslået 1RM, topløft",
  "All workouts": "Alle træninger",
  "Performance report": "Præstationsrapport",
  "Your training on paper: totals, charts, new bests and every set. Frame it, print it or send it to your coach.": "Din træning på papir: totaler, grafer, nye rekorder og hvert eneste sæt. Sæt den i ramme, print den eller send den til din træner.",
