  "Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.": "Tomt overlader vægten til din progression. En %1RM regnes ud fra dit bedste anslåede 1RM.",
  "End programme": "Afslut program",
  "End “{0}”?": "Afslut “{0}”?",
