  "Profile default ({0})": "Profilens standard ({0})",
  "For gyms that mix kg and lb. This exercise is shown and typed in it everywhere, plates and steps included. Totals in Stats stay in {0}.": "Til centre, der blander kg og lb. Denne øvelse vises og indtastes i den overalt, skiver og trin inklusive. Totaler i Statistik forbliver i {0}.",
  "Back to top": "Til toppen",
  "A one-minute walk around the app": "En gåtur på ét minut rundt i appen",
  "A practice workout": "En øvetræning",
  "Backups, imports and syncing with your own server.": "Backups, import og synkronisering med din egen server.",
  "Body map": "Kropskort",
  "Catch your breath": "Få pusten igen",
  "Done with a set? Tick it. Go on, try it.": "Færdig med et sæt? Kryds det af. Kom bare, prøv det.",
  "Filter it down": "Snævr det ind",
  "Find any exercise": "Find enhver øvelse",
  "Finish line": "Målstregen",
  "Finish saves the session and moves your weights along. This practice one just quietly disappears.": "Afslut gemmer træningen og rykker dine vægte videre. Denne øvetræning forsvinder bare stille og roligt.",
  "Finish the tour?": "Gør rundturen færdig?",
  "Finish your workout first, then the tour is all yours.": "Afslut din træning først, så er rundturen din.",
  "Kilos or pounds, and the language you like best.": "Kilo eller pund, og det sprog, du bedst kan lide.",
  "Let’s go": "Kom så",
  "Make it yours": "Gør den til din egen",
  "Muscles at a glance": "Musklerne på et øjeblik",
  "Narrow the list by body part, type or the equipment you have.": "Snævr listen ind efter kropsdel, type eller det udstyr, du har.",
  "No thanks": "Nej tak",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "Vælg en øvelse for at se dens bedste sæt, anslået max og hvor det er på vej hen.",
  "Pointing at: {0}": "Peger på: {0}",
  "Practice run": "Øvetur",
  "Programmes and sharing": "Programmer og deling",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "Programmer, startplaner og deling af en plan med en ven gemmer sig bag denne knap.",
  "Records": "Rekorder",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "Skema siger hvornår, Rutiner siger hvad. Byg dine egne, eller snup en startplan.",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "Søg i tusindvis af øvelser på dit sprog. Giv dine favoritter en stjerne, så flyder de op til toppen.",
  "See which muscles got the work and which still need rest. Tap one for details.": "Se, hvilke muskler der fik arbejdet, og hvilke der stadig skal hvile. Tryk på en for detaljer.",
  "Show me": "Vis mig",
  "Show the tour again": "Vis rundturen igen",
  "Skip tour": "Spring rundturen over",
  "Step {0} of {1}": "Trin {0} af {1}",
  "Swipe a set": "Swipe et sæt",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "Swipe et sæt til siden for at kopiere eller fjerne det. Dets nummer åbner endnu mere.",
  "The big Start button": "Den store Start-knap",
  "The little body shows what each day works, so leg day can’t hide.": "Den lille krop viser, hvad hver dag træner, så bendagen ikke kan gemme sig.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "Pausetimeren starter af sig selv. Læg tid til, eller spring den over, hvis du føler dig heroisk.",
  "The ⋯ menu": "Menuen ⋯",
  "Theme, accent colour and what Home shows.": "Tema, accentfarve og hvad Hjem viser.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "Den her er på skrømt, intet bliver gemt. Hver række er et sæt: vægt, så gentagelser. Tryk på et tal for at ændre det.",
  "Tick it off": "Kryds det af",
  "Today at a glance": "I dag på et øjeblik",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "Dagens træning bor her. Ét tryk, og du løfter. På en hviledag står der det, helt uden dårlig samvittighed.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "Træn på faste ugedage, eller kør dine rutiner i et loop, hvor den næste venter på dig.",
  "Want a 1-minute tour?": "Lyst til en rundtur på 1 minut?",
  "Week or rotation": "Uge eller rotation",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "Vi peger de gode ting ud på de rigtige skærme. Hop fra når som helst.",
  "Workout settings, layouts, notes and extra exercises hide in here.": "Træningsindstillinger, layouts, noter og ekstra øvelser gemmer sig herinde.",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "Træninger, streaks og alt, hvad du har løftet. Det fyldes op, mens du træner.",
  "You stopped halfway. Want to see the rest?": "Du stoppede halvvejs. Vil du se resten?",
  "Your data, your backups": "Dine data, dine backups",
  "Your progress": "Dine fremskridt",
  "Your routines": "Dine rutiner",
  "You’re set": "Du er klar",
  "Previous year": "Forrige år",
  "Next year": "Næste år",
  "Pick a month": "Vælg en måned",
  "Pick a day": "Vælg en dag",
  "With pictures": "Med billeder",
  "A small picture next to each exercise, like a plan from the gym.": "Et lille billede ved hver øvelse, som et program fra centret.",
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "Det her findes i openGym-appen til telefonen: Apple Health på iPhone, Health Connect på Android.",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Webhooks sendes af din egen openGym-server, så du skal have en. Forbind denne enhed til den under Konto.",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "Webhooks er slået fra på denne server. Tilføj INTEGRATIONS=webhook i dens .env og genstart den.",
  "The MCP server runs next to your own openGym server and reads your data there.": "MCP-serveren kører ved siden af din egen openGym-server og læser dine data der.",
  "Only what you switch on talks to anything. The rest stays out of your way.": "Kun det, du slår til, snakker med noget. Resten holder sig af vejen.",
  "Could not reach your server": "Kunne ikke nå din server",
  "Tap to try again": "Tryk for at prøve igen",
  "Disconnect {0}?": "Afbryd {0}?",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGym holder op med at skrive og læse. Det, den allerede har skrevet, kan blive der som dine data eller forsvinde.",
  "Works with": "Virker med",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "Ingen ekstra forbindelse nødvendig: de skriver til {0}, og openGym læser derfra.",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "Ingen ekstra forbindelse nødvendig: de skriver til Apple Health eller Health Connect, og openGym-appen til telefonen læser derfra.",
  "{0} has no direct line to openGym, and it does not need one.": "{0} har ingen direkte linje til openGym, og den har heller ikke brug for en.",
  "How it gets here": "Sådan kommer det hertil",
  "{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.": "{0} gemmer i Apple Health på iPhone eller Health Connect på Android. openGym læser derfra.",
  "What openGym reads": "Hvad openGym læser",
  "What it does not do": "Hvad den ikke gør",
  "Workouts logged in openGym go to the health store, not back into {0} itself.": "Træninger logget i openGym havner i sundhedsdataene, ikke tilbage i selve {0}.",
  "Set up {0}": "Opsæt {0}",
