  "An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.": "En øvelses historik, rekorder og fremskridt regnes ud fra dine træninger. Ret træningen, så følger de med.",
  "Back home, practice over. Stats is where the gains pile up. Tap it.": "Hjemme igen, øvelsen er slut. Statistik er der, hvor fremskridtene hober sig op. Tryk på den.",
