  "Your real data is exactly as you left it.": "Dine rigtige data er præcis, som du efterlod dem.",
  "Your routines live behind this tab. Tap Plan.": "Dine rutiner bor bag denne fane. Tryk på Plan.",
  "Your sets, weigh-ins and measurements as CSV. Our importer reads it back too.": "Dine sæt, vejninger og mål som CSV. Vores import kan også læse den ind igen.",
  "Date, duration, share, export, delete": "Dato, varighed, del, eksportér, slet",
  "Rewrite the session note whenever.": "Omskriv træningens note når som helst.",
  "Wrong day or forgot to finish on time? Fix it in here. Sharing, export and Delete live here too.": "Forkert dag eller glemte at afslutte til tiden? Ret det herinde. Deling, eksport og Slet bor også her.",
