  "Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.": "Almindelig http:// virker kun for en adresse på dit hjemmenetværk, som 192.168.x.x, et .local-navn eller en Tailscale 100.x-adresse. Alt på internettet kræver https://.",
  "Plain http only on your home network": "Almindelig http kun på dit hjemmenetværk",
