  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "Bygget ud fra din arbejdsvægt og afrundet til centrets skiver og håndvægte. En øvelse kan vælge sin egen i sine indstillinger.",
