  "Follows Settings → Workout → Automatic warm-ups.": "Følger Indstillinger → Træning → Automatisk opvarmning.",
  "For this workout": "For denne træning",
  "Heavy lifts get more rungs, light ones one or none.": "Tunge løft får flere trin, lette ét eller ingen.",
  "It hurts": "Det gør ondt",
  "It hurts, it’s taken, no time, feeling great": "Det gør ondt, den er optaget, ingen tid, føler mig stærk",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Det nimmer, så lettere resten af vejen. Stop, hvis det stadig gør ondt.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Det nimmer, så dine resterende sæt går til en bevægelse, der belaster samme muskel fra en venligere vinkel.",
  "Keep these warm-ups": "Behold disse opvarmningssæt",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Gemt. Samme opvarmning næste gang, tilpasset din arbejdsvægt.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Loggede sæt og din rutine forbliver som de er. Coachen er ikke læge eller fysioterapeut. Hvis noget gør ondt, så spørg en fagperson.",
  "Looking at your workout…": "Kigger på din træning…",
