  "Nothing to change. Carry on as planned.": "Intet at ændre. Fortsæt som planlagt.",
  "One set less keeps the session doable today and still counts.": "Ét sæt mindre gør træningen til at klare i dag og tæller stadig.",
  "Only the warm-ups you plan yourself.": "Kun de opvarmningssæt, du selv planlægger.",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "Trappet op fra arbejdsvægten: flere trin, når det er tungt, færre, når det er let.",
  "Remove warm-up {0}": "Fjern opvarmning {0}",
  "Revise programme “{0}”": "Revidér programmet “{0}”",
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "Rutiner, øvelser, sæt og gentagelser, opvarmning, programmer, dit ugeskema, progressionsindstillinger og hvad dit center kan lægge på.",
  "Running on empty": "Kører på reserven",
  "Saved in the routine, scaled to your work weight": "Gemt i rutinen, tilpasset din arbejdsvægt",
