  "Short on time": "Kort tid",
  "Skip the rest of {0}": "Spring resten af {0} over",
  "Something else": "Noget andet",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Squats, presses, roninger og venner får en opbygning. Curls og raises starter kolde.",
  "Straight into the work sets.": "Direkte ind i arbejdssættene.",
  "That workout is over, so these can’t be applied any more.": "Den træning er slut, så disse kan ikke anvendes længere.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Appen trapper op fra din arbejdsvægt: flere opvarmningssæt, når det er tungt, færre, når det er let, med dit centers skiver.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Stativet er optaget, så tag den til sidst. Resten af træningen har ikke brug for det.",
  "There’s no workout running.": "Der kører ingen træning.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Disse opvarmningssæt kommer før arbejdssættene hver træning, som andel af arbejdsvægten, så de vokser med den.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Det her er demoen, så der er ingen AI-model bag mig. På din egen server læser jeg din træning og foreslår ændringer som disse.",
  "Warm-up {0}": "Opvarmning {0}",
  "Warm-ups": "Opvarmning",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "Hvad sker der? Coachen foreslår et par ændringer til resten af denne træning. Loggede sæt forbliver som de er.",
  "Where, and what movement hurts? (optional)": "Hvor, og hvilken bevægelse gør ondt? (valgfrit)",
