  "You can keep training, the answer waits here and in the Coach.": "Du kan træne videre, svaret venter her og hos coachen.",
  "You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.": "Du føler dig stærk, så lidt mere på stangen resten af vejen. Ikke et nyt max, bare et lille skub.",
  "Your rows, as a share of the work weight, so they grow with it.": "Dine rækker, som andel af arbejdsvægten, så de vokser med den.",
