  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "Gem op til 2 frysninger, én for hver 4 trænede uger. Selv to missede uger i træk kan dækkes.",
  "Change the freeze rule": "Skift frysningsreglen",
