  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Misser du en uge, dækker en frysning den: din streak fortsætter, den uge lægger bare ikke noget til. To missede uger i træk, og den starter forfra.",
