  "{0} sees only what is on here.": "{0} ser kun det, der er slået til her.",
  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "Du lader denne træner se de kategorier, der er markeret her, og ændre dem, der er markeret som foreslå eller anvend. Hvis træneren arbejder for et center, ser centerlederen kategorierne i sin række, aldrig mere end at se. Du kan ændre det eller afbryde når som helst, og det holder op med at virke i samme øjeblik. Hvert kig og hver ændring skrives i din delingslog, som kun du kan læse.",
