  "This profile is linked to your {0} account, so signing in there signs you in here.": "Denne profil er forbundet med din {0}-konto, så logger du ind der, er du logget ind her.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "Denne server kræver invitation, og {0} alene får dig ikke ind. Spørg den, der driver den.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "På denne server logger alle ind med {0}. Ny her? Når du logger ind, oprettes din profil.",
