  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} er den eneste vej ind i denne profil, så den forbliver forbundet. Tilføj en adgangsnøgle først.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} lukkede dig ind, men denne server tager kun bestemte grupper. Bed den, der driver den, om at tilføje dig.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} sendte noget tilbage, vi ikke kunne bekræfte, så ingen blev logget ind. Sker det igen, viser admin-siden hvorfor.",
