  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Kropsfedt og fedtfri masse, som din vægt gemte dem. Vises under Kropsmål og blandes aldrig med det, du logger.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Kropsfedt, fedtfri masse, knoglemasse, kropsvæske og BMR, som din vægt gemte dem. Vises under Kropsmål og blandes aldrig med det, du logger.",
