  "A buzz for each phase": "En vibration for hver fase",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "En kopi af alt, én gang om dagen, i din egen mappe: Nextcloud, ownCloud, en NAS, alt, der taler WebDAV. Din server, ingen andres.",
  "A sound for each kind of rest": "En lyd for hver slags pause",
