  "Calendar feed off": "Kalenderfeed fra",
  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "Kondition uploades som det, det var: en løbetur, en cykeltur, en rotur. Styrke som Weight Training, med hvert sæt i beskrivelsen.",
  "Change server or password": "Skift server eller adgangskode",
  "Check the connection": "Tjek forbindelsen",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "Forbind Strava én gang fra openGym i en browser, logget ind på din server. Derefter uploades dine træninger fra serveren, uanset hvilken enhed du logger dem på.",
