  "No tempo": "Intet tempo",
  "Open in my calendar app": "Åbn i min kalender-app",
  "Pick one. You choose whether it replaces what is here or merges with it.": "Vælg en. Du bestemmer, om den erstatter det, der er her, eller flettes sammen med det.",
  "Reconnect": "Forbind igen",
  "Rep {0} of {1}": "Rep {0} af {1}",
  "Restore from a backup": "Gendan fra en backup",
  "Same as the rest ({0})": "Samme som resten ({0})",
  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "Sekunder for hver del af en rep: ned, pause, op, klem. 3-1-1-0 er tre ned, et i bunden, et op, direkte videre til næste.",
  "Show finished workouts too": "Vis også færdige træninger",
  "Strava connected. Your next workout goes up by itself.": "Strava forbundet. Din næste træning uploades af sig selv.",
  "Strava disconnected": "Strava afbrudt",
  "Strava is listening": "Strava lytter",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "Strava er slået fra på denne server. Registrer en Strava API-app, tilføj så strava til INTEGRATIONS og dens STRAVA_CLIENT_ID og STRAVA_CLIENT_SECRET til .env, og genstart.",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Uploads til Strava kommer fra din egen openGym-server, så du skal have en. Forbind denne enhed til den under Konto.",
  "Strength workouts too": "Også styrketræninger",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "Abonner på dette link i din kalender-app. Alle med linket ser din plan, så hold det for dig selv.",
  "Tempo": "Tempo",
  "Tempo for this set": "Tempo for dette sæt",
  "Tempo {0}": "Tempo {0}",
  "Tempo {0}, start the guide": "Tempo {0}, start guiden",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "Kalenderlinket kommer fra din egen openGym-server, så du skal have en. Forbind denne enhed til den under Konto.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "Linket holder op med at virke med det samme. Det, din kalender allerede viser, kan blive, til den opdateres.",
  "The old link stops working, and every calendar that uses it needs the new one.": "Det gamle link holder op med at virke, og alle kalendere, der bruger det, skal have det nye.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "Adgangskoden bliver på denne enhed, i dens sikre lager. Den synkroniseres aldrig og kommer aldrig med i en backup.",
  "The server cannot show this link again. Make a new one.": "Serveren kan ikke vise dette link igen. Lav et nyt.",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "Denne enhed holder op med at tage backup og glemmer adgangskoden. Backups, der allerede ligger i mappen, bliver der.",
  "Tick the set": "Afkryds sættet",
  "Turn off": "Slå fra",
  "Turn off the calendar feed?": "Slå kalenderfeedet fra?",
  "Up as fast as you can. The guide gives it one quick second.": "Op så hurtigt du kan. Guiden giver det ét hurtigt sekund.",
  "Uploading": "Uploader",
  "User name": "Brugernavn",
  "WebDAV backup": "WebDAV-backup",
  "When the app is open, at most once a day, on this device.": "Når appen er åben, højst én gang om dagen, på denne enhed.",
  "Your planned sessions in Apple Calendar, Google Calendar or Outlook, kept up to date. A private link only your calendar knows.": "Dine planlagte træninger i Apple Kalender, Google Kalender eller Outlook, altid opdateret. Et privat link, kun din kalender kender.",
  "Your server forgets the sign-in and stops uploading. What is on Strava stays, and the Strava app keeps its access until you remove it on strava.com.": "Din server glemmer loginet og holder op med at uploade. Det, der er på Strava, bliver, og Strava-appen beholder sin adgang, til du fjerner den på strava.com.",
  "{0} s per rep, a guide in the workout counts it for you.": "{0} s per rep, en guide i træningen tæller for dig.",
  "{0} s under tension": "{0} s under spænding",
  "{0} s under tension. Lovely and slow.": "{0} s under spænding. Dejligt langsomt.",
  "Backups & calendar": "Backups & kalender",
  "A copy every day in your own Nextcloud or any WebDAV folder.": "En kopi hver dag i din egen Nextcloud eller en hvilken som helst WebDAV-mappe.",
  "The full backup, once a day while the app is open, and whenever you tap Back up now.": "Hele backuppen, én gang om dagen, mens appen er åben, og hver gang du trykker på Tag backup nu.",
  "Restore it on a new phone in two taps.": "Gendan den på en ny telefon med to tryk.",
  "Your planned sessions in Apple, Google or Outlook calendar.": "Dine planlagte træninger i Apple-, Google- eller Outlook-kalenderen.",
  "Planned sessions from a week back to eight weeks ahead, as all-day events.": "Planlagte træninger fra en uge tilbage til otte uger frem, som heldagsbegivenheder.",
  "Finished workouts too, if you like.": "Også færdige træninger, hvis du vil.",
  "Your runs, rides and rows go up to Strava, strength too if you like.": "Dine løbeture, cykelture og roture kommer på Strava, styrke også, hvis du vil.",
  "Finished cardio workouts, with their time and distance.": "Færdige konditionstræninger, med tid og distance.",
  "Strength sessions as Weight Training, if you switch it on.": "Styrketræninger som Weight Training, hvis du slår det til.",
  "After a warm-up set": "Efter et opvarmningssæt",
  "The ramp is still going.": "Opvarmningen er stadig i gang.",
  "Between working sets": "Mellem arbejdssæt",
  "Same exercise, next set.": "Samme øvelse, næste sæt.",
  "Between superset rounds": "Mellem supersætrunder",
  "Back to the top of the superset.": "Tilbage til toppen af supersættet.",
  "Before the next exercise": "Før næste øvelse",
  "Time to move on.": "Tid til at komme videre.",
  "Lower": "Ned",
  "Lift": "Op",
  "Squeeze": "Klem",
  "Lower (s)": "Ned (s)",
  "Pause at the bottom (s)": "Pause i bunden (s)",
