  "Squeeze at the top (s)": "Klem i toppen (s)",
  "The server did not take that name and password. An app password usually works best.": "Serveren godtog ikke det navn og den adgangskode. En app-adgangskode virker som regel bedst.",
  "That folder is not there, and openGym could not make it. Make it on the server first.": "Den mappe findes ikke, og openGym kunne ikke oprette den. Opret den på serveren først.",
  "The server says this account may not write there.": "Serveren siger, at denne konto ikke må skrive der.",
  "The server is out of space for this account.": "Serveren er løbet tør for plads til denne konto.",
  "Could not reach the server. In a browser it also has to allow this site (CORS), see the guide.": "Kunne ikke nå serveren. I en browser skal den også tillade denne side (CORS), se guiden.",
  "Type the password again: this device does not have it.": "Skriv adgangskoden igen: denne enhed har den ikke.",
  "That file is not an openGym backup.": "Den fil er ikke en openGym-backup.",
  "Nothing to back up yet: log a workout first.": "Intet at tage backup af endnu: log en træning først.",
  "The server answered with an error.": "Serveren svarede med en fejl.",
  "Paste the address of the folder on your WebDAV server.": "Indsæt adressen på mappen på din WebDAV-server.",
  "That does not look like an address.": "Det ligner ikke en adresse.",
  "Leave the name and password out of the address, they have their own fields.": "Hold navn og adgangskode ude af adressen, de har deres egne felter.",
  "Strava was not given access. Nothing was connected.": "Strava fik ikke adgang. Intet blev forbundet.",
  "Strava has to be allowed to upload activities. Connect again and leave that box ticked.": "Strava skal have lov til at uploade aktiviteter. Forbind igen, og lad det felt være afkrydset.",
  "That sign-in took too long or came from somewhere else. Start again from here.": "Det login tog for lang tid eller kom fra et andet sted. Start forfra herfra.",
  "Sign in to your server first, then connect Strava.": "Log ind på din server først, og forbind så Strava.",
  "Strava is off on this server.": "Strava er slået fra på denne server.",
  "Strava could not be connected. Try again.": "Strava kunne ikke forbindes. Prøv igen.",
  "Keeps the newest {0} backup, one per day.": "Beholder den nyeste {0} backup, én per dag.",
  "Keeps the newest {0} backups, one per day.": "Beholder de nyeste {0} backups, én per dag.",
  "Steady double progression": "Jævn dobbelt progression",
  "Undulating days": "Skiftende dage",
  "Shorter rests": "Kortere pauser",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Arbejd dig op gennem et rep-interval én rep ad gangen. Hvert sæt skal ramme målet, før det rykker, og i toppen af intervallet går vægten op.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Hver træning skifter: en mellemdag med dine reps, en tung dag med færre, en let dag med flere. Vægtene kommer fra dit estimerede max, så de stiger, når du bliver stærkere.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Samme vægt, lidt kortere pause hver gang alle sæt er rene. Ved din korteste pause går vægten op, og pausen starter forfra.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Hvert sæt ramte {0}. Samme vægt, {1} reps denne gang.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Ikke alle sæt har nået {0} endnu. Samme vægt og mål igen ({1} af {2} tilbage).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Alle sæt rene. Samme vægt med {0} s kortere pause: {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Rent ved din korteste pause. {0} {1} mindre hjælp, pausen tilbage til {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Rent ved din korteste pause. {0} {1} mere, pausen tilbage til {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Fast i {0} træninger. Samme vægt med længere pause: {1} s.",
