  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "Denne version af openGym kommer uden Garmin-forbindelsen, fordi Garmins del af den ikke er open source. Versionerne fra App Store, Google Play og GitHub har den.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "Garmin Connect er ikke på denne telefon. Installer den, par dit ur der, og kom så tilbage hertil.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Garmin Connect skal opdateres, før openGym kan tale med dit ur.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Kunne ikke nå Garmin Connect. Prøv igen om et øjeblik.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Vælg din Garmin i Garmin Connect, så dukker dine træninger op på håndleddet.",
  "Your Garmin isn’t in reach right now. Bring it close with Bluetooth on, and this page catches up by itself.": "Din Garmin er ikke inden for rækkevidde lige nu. Tag den tættere på med Bluetooth slået til, så følger siden selv med.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect kender ikke noget ur endnu. Par dit der først.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym er på din Garmin. Sæt, du logger på håndleddet, lander her.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym er på din Garmin. Den indhenter det, så snart uret er inden for rækkevidde.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Din Garmin er her, men openGym er ikke på den endnu. Hent den, og åbn den én gang på uret.",
