  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Fire tryk om søvn, energi, ømhed og stress. På en hård dag tilbyder openGym at tage det lettere, og efter et par uger ser du, hvad dine gode dage har til fælles.",
