  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "Ingen kortsøgning i openGym Offline. Stil dig i dit center, tryk på Nuværende placering, færdig.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Ikke en eneste byte har forladt denne telefon. Din træning vedkommer ingen andre end dig.",
