  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "Intet logget i et stykke tid. Er du færdig, slutter den af sig selv kl. {0}, gemt ved dit sidste sæt.",
  "Forgotten workouts": "Glemte træninger",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Svarer ingen, afsluttes den af sig selv og smider aldrig noget væk. Slutningen er dit sidste sæt plus dets pause, så tiden forbliver ærlig. Genåbn den fra Historik i et døgn. Dit ur spørger også.",
