  "Needs iOS 17 or later. No animations on the Lock Screen, so the exercise picture is a still. Buttons work without unlocking, Finish opens the app.": "Kræver iOS 17 eller nyere. Ingen animationer på låseskærmen, så øvelsesbilledet står stille. Knapperne virker uden at låse op, Afslut åbner appen.",
