  "The Dynamic Island holds four tiles. It is an island, not a continent.": "Dynamic Island rummer fire fliser. Det er en ø, ikke et kontinent.",
  "The pill": "Pillen",
  "The pill has two spots, one each side of the camera.": "Pillen har to pladser, én på hver side af kameraet.",
  "The pill shows two tiles beside the camera. Long-press it for the rest.": "Pillen viser to fliser ved siden af kameraet. Tryk længe for resten.",
