  "Three buttons fit in the Dynamic Island.": "Tre knapper kan være i Dynamic Island.",
  "Tiles": "Fliser",
  "Tiles become lines of text, so Android 16 can keep it a Live Update by the clock. While a rest runs, the notification shows its rest buttons.": "Fliserne bliver til tekstlinjer, så Android 16 kan beholde den som Live Update ved uret. Mens en pause kører, viser notifikationen sine pauseknapper.",
  "Up to three lines under the set. The widget keeps its own − and + buttons.": "Op til tre linjer under sættet. Widgetten beholder sine egne − og + knapper.",
