  "Code from OpenRouter": "Kode fra OpenRouter",
  "Daily check-ins, sleep, resting heart rate, HRV and steps from your phone, and blood pressure. Off until you switch it on.": "Daglige check-ins, søvn, hvilepuls, HRV og skridt fra din telefon samt blodtryk. Slået fra, til du slår det til.",
  "Estimated one-rep maxes of your main lifts over the last twelve weeks.": "Estimerede 1RM for dine hovedløft over de seneste tolv uger.",
  "Find it for me": "Find den for mig",
  "For questions that need facts from outside your training, like a study or a product.": "Til spørgsmål, der kræver fakta uden for din træning, fx en undersøgelse eller et produkt.",
  "From the routines library": "Fra rutinebiblioteket",
  "GPT, with an API key": "GPT, med en API-nøgle",
  "Gemini, with a free tier to start": "Gemini, med et gratis niveau at starte på",
  "Get a key from {0}": "Hent en nøgle fra {0}",
  "Health and how you feel": "Helbred og hvordan du har det",
  "How it’s done": "Sådan gøres den",
  "It shows up under Settings → API tokens, where you can revoke it any time.": "Den vises under Indstillinger → API-tokens, hvor du kan tilbagekalde den når som helst.",
  "Looks for Ollama, LM Studio and llama.cpp on the machine running your openGym server and on this phone.": "Leder efter Ollama, LM Studio og llama.cpp på maskinen, der kører din openGym-server, og på denne telefon.",
  "Nothing answered. Type its address below, like http://192.168.1.20:11434.": "Intet svarede. Skriv adressen nedenfor, fx http://192.168.1.20:11434.",
  "Ollama or LM Studio at home, nothing leaves your Wi-Fi": "Ollama eller LM Studio derhjemme, intet forlader dit wifi",
  "On my network": "På mit netværk",
  "One sign-in for Claude, GPT, Gemini and more": "Ét login til Claude, GPT, Gemini og flere",
  "OpenRouter makes a key just for this phone, billed to your OpenRouter credits. You can revoke it there any time.": "OpenRouter laver en nøgle kun til denne telefon, betalt med dine OpenRouter-kreditter. Du kan tilbagekalde den der når som helst.",
  "Or paste a key": "Eller indsæt en nøgle",
